package net.scubadive.client.creature.vanilla;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * Saddle for the renewed nautilus, sitting on the crown of the coil (same root pivot as the body).
 * Generated by tools/V2_vanilla.py from the V1 parts (thin pattern boxes are painted into the texture);
 * edit the script, not this file. The texture PNG is 4x the declared size (quarter-pixel detail).
 */
final class NautilusSaddleGeometry {
	static final int TEX_W = 64;
	static final int TEX_H = 16;

	private NautilusSaddleGeometry() {
	}

	static LayerDefinition createLayer() {
		MeshDefinition mesh = new MeshDefinition();
		PartDefinition root = mesh.getRoot();
		PartDefinition b_main = root.addOrReplaceChild("main", cubes_main(), PartPose.offset(0f, 15.5f, 1.5f));
		return LayerDefinition.create(mesh, TEX_W, TEX_H);
	}

	private static CubeListBuilder cubes_main() {
		CubeListBuilder c = CubeListBuilder.create();
		c.texOffs(0, 0).addBox(-3f, -4.6996f, -1.8285f, 6f, 0.5f, 6f);
		c.texOffs(30, 0).addBox(-2.5f, -5.4496f, -1.3285f, 5f, 0.75f, 5f);
		c.texOffs(0, 7).addBox(-2.25f, -6.4496f, 2.6715f, 4.5f, 1f, 1f);
		c.texOffs(11, 7).addBox(-1.25f, -5.9496f, -1.3285f, 2.5f, 0.5f, 0.75f);
		c.texOffs(24, 0).addBox(3.3f, -4.7248f, 0.5465f, 0.25f, 5.75f, 1.25f);
		c.texOffs(50, 0).addBox(3.55f, -1.5f, 0.4215f, 0.25f, 1.25f, 1.5f);
		c.texOffs(27, 0).addBox(-3.55f, -4.7248f, 0.5465f, 0.25f, 5.75f, 1.25f);
		c.texOffs(54, 0).addBox(-3.8f, -1.5f, 0.4215f, 0.25f, 1.25f, 1.5f);
		return c;
	}
}
